LOCK TABLES `freeboard` WRITE;
/*!40000 ALTER TABLE `freeboard` DISABLE KEYS */;
INSERT INTO `freeboard` VALUES (1,1,'서비스 점검 안내 (2024-06-01)','안녕하세요, 애니핑입니다. 6월 1일 새벽 2시부터 4시까지 서버 점검이 진행될 예정입니다. 이용에 불편을 드려 죄송합니다.',120,0,'2026-02-12 13:47:10',NULL,NULL),(2,1,'신규 기능 업데이트 안내','캐릭터 게시판 기능이 새롭게 추가되었습니다! 많은 이용 부탁드립니다.',350,0,'2026-02-12 13:47:10',NULL,NULL),(3,1,'개인정보 처리방침 변경 안내','개인정보 처리방침이 일부 변경되었습니다. 자세한 내용은 공지사항을 확인해주세요.',80,0,'2026-02-12 13:47:10',NULL,NULL),(4,1,'5월 이벤트 당첨자 발표','5월 가정의 달 이벤트 당첨자를 발표합니다! 당첨되신 분들께는 개별 연락 드렸습니다.',500,0,'2026-02-12 13:47:10',NULL,NULL),(5,1,'커뮤니티 이용 수칙 안내','건전한 커뮤니티 문화를 위해 이용 수칙을 준수해 주시기 바랍니다.',200,0,'2026-02-12 13:47:10',NULL,NULL),(6,1,'서버 불안정 현상에 대한 사과문','지난 주말 발생한 서버 불안정 현상에 대해 사과드립니다. 재발 방지를 위해 최선을 다하겠습니다.',150,0,'2026-02-12 13:47:10',NULL,NULL),(7,1,'4월 베스트 리뷰 선정 안내','4월 한 달간 작성된 리뷰 중 베스트 리뷰를 선정했습니다. 축하드립니다!',300,0,'2026-02-12 13:47:10',NULL,NULL),(8,1,'사이트 리뉴얼 안내','애니핑 사이트가 새롭게 리뉴얼되었습니다. 더 편리해진 기능을 경험해보세요.',600,0,'2026-02-12 13:47:10',NULL,NULL),(9,1,'회원 등급 제도 변경 안내','회원 등급 산정 기준이 변경되었습니다. 마이페이지에서 확인해주세요.',250,0,'2026-02-12 13:47:10',NULL,NULL),(10,1,'불법 게시물 단속 강화 안내','저작권 침해 등 불법 게시물에 대한 단속을 강화합니다.',180,0,'2026-02-12 13:47:10',NULL,NULL),(11,1,'3월 이벤트 안내','새학기 맞이 이벤트를 진행합니다. 많은 참여 부탁드립니다.',400,0,'2026-02-12 13:47:10',NULL,NULL),(12,1,'모바일 앱 출시 예정 안내','애니핑 모바일 앱이 곧 출시됩니다! 사전 예약하고 혜택 받아가세요.',700,0,'2026-02-12 13:47:10',NULL,NULL);
